import {mountProjectShell,mountProjectAccessShell} from './application-shell.mjs';
import {capabilities,hasCapability,requireCapability} from './capabilities.mjs';
import {createSnapshot,validateSnapshot,localFromSnapshot,normaliseMetadata,normaliseMeasurement,measurementTypes,compareRevisions,instrumentFields} from './domain.mjs';
import {createProjectStore,projectURL,normaliseProject} from '../electronics/state/project.mjs';
import {deploymentPath} from '../deployment.mjs';
import {buildSheetModel,renderBuildSheet} from './documents.mjs';
export function createForgeProjectApp({root,status,auth,repository,storage=globalThis.localStorage,session=globalThis.sessionStorage,location=globalThis.location,navigate=url=>location.assign(url),download=defaultDownload}={}){
 const doc=root.ownerDocument,e=(tag,text)=>{const node=doc.createElement(tag);if(text!=null)node.textContent=text;return node;},store=createProjectStore(storage);
 let shellInstance=null,activeView='library',metadataDraft=null;let grants=[],projects=[],templates=[],project=null,revisions=[],measurements=[],documents=[],busy=false,epoch=0,identity=null,subscription,fieldSequence=0,comparisonResult=null;
 const can=name=>hasCapability(grants,capabilities[name]);
 const say=message=>{status.textContent=message;};
 function link(parent,text,url){const a=e('a',text);a.href=deploymentPath(url);parent.append(a);return a;}
 function button(parent,text,run,{disabled=false}={}){const b=e('button',text);b.type='button';b.disabled=disabled||busy;b.addEventListener('click',()=>perform(run));parent.append(b);return b;}
 function rememberDraft(){const f=root.querySelector('form[data-project-metadata]');if(f&&project)metadataDraft={project_id:project.id,version:project.version,dirty:f.dataset.dirty==='true',values:Object.fromEntries([...f.querySelectorAll('input,select,textarea')].map(n=>[n.name,n.value]))};}
 async function perform(run){if(busy){say('A cloud action is already in progress.');return;}rememberDraft();busy=true;root.setAttribute('aria-busy','true');const disabledBefore=new Map([...root.querySelectorAll('button')].map(b=>[b,b.disabled]));for(const b of disabledBefore.keys())b.disabled=true;const generation=epoch;let succeeded=false;say('Saving / loading…');try{const message=await run();succeeded=true;if(generation===epoch)say(message||'Done.');}catch(error){if(generation===epoch)say(error.message||'Request failed. Your local original remains available.');}finally{busy=false;root.removeAttribute('aria-busy');if(generation===epoch){if(succeeded)render();else for(const [b,disabled] of disabledBefore)b.disabled=disabled;}}}
 function field(form,name,label,value='',{type='text',max=200,required=false,options}={}){const l=e('label',label),n=e(options?'select':name==='notes'||name==='revision_note'?'textarea':'input');n.name=name;n.id='forge-pro-'+name+'-'+(++fieldSequence);n.value=value??'';if(options){for(const v of options){const o=e('option',v);o.value=v;n.append(o);}n.value=value??options[0];}else{n.type=type;n.maxLength=max;n.required=required;if(type==='number'){n.step='any';n.min='0';}}l.append(n);form.append(l);return n;}
 const value=(form,name)=>form.elements.namedItem(name)?.value??'';
 function metadata(form){const instrument={};for(const key of instrumentFields){const v=value(form,'instrument_'+key);if(v!=='')instrument[key]=key==='year'?Number(v):v;}return normaliseMetadata({title:value(form,'title'),notes:value(form,'notes'),instrument});}
 function submit(form,label,run){const b=e('button',label);b.type='submit';form.append(b);form.addEventListener('invalid',()=>say('Check the marked project fields before saving.'),true);form.addEventListener('submit',event=>{event.preventDefault();if(form.checkValidity())perform(()=>run(form));});}
 async function refresh(){projects=await repository.list();templates=can('templates')?await repository.templates():[];}
 async function select(id){comparisonResult=null;project=await repository.project(id);if(!project||project.owner_id!==identity.id)throw Error('This project is unavailable to your account.');const results=await Promise.all([repository.revisions(id),can('measurements')?repository.measurements(id):[],can('documents')?repository.documents(id):[]]);[revisions,measurements,documents]=results;if(!revisions.some(r=>r.id===project.current_revision_id))throw Error('The current revision could not be loaded.');await repository.command('open',{project_id:id});activeView='instrument';const url=new URL(location.href);url.searchParams.set('project',id);doc.defaultView.history.replaceState(null,'',url.pathname+url.search);}
 function current(){return revisions.find(r=>r.id===project.current_revision_id);}
 function pending(){try{const p=JSON.parse(session.getItem('apparition.forge-pro.pending')||'null');return p&&p.owner_id===identity.id&&p.project_id===project.id?normaliseProject(p.local):null;}catch{return null;}}
 function render(){
  shellInstance?.destroy();shellInstance=null;root.replaceChildren();root.before(status);root.removeAttribute('data-project-id');if(!identity){const access=e('section');access.append(e('h2','Try Forge Pro Preview'),e('p','Professional project tools are available during development. Sign in or create an account and confirm your email, then follow the Projects link in your account. Your projects stay private; preview availability may change.'));link(access,'Sign in / create an account','/account/');link(access,'Continue designing in Free Forge','/circuit-forge/');shellInstance=mountProjectAccessShell({root,status,content:access});return;}
  if(!can('cloud')){const access=e('section');access.append(e('h2','Professional workflow preview'),e('p','Preview access is unavailable for this account. Cloud projects require a Forge Pro capability. No plan can be purchased here yet. Your Free editor, local saves, circuit sharing and wiring exports remain available.'));link(access,'Open Free Forge','/circuit-forge/');shellInstance=mountProjectAccessShell({root,status,content:access,eligible:true});return;}
  const library=e('section');library.setAttribute('aria-label','Your projects');library.className='forge-pro-library';library.append(e('h2','Your instruments / projects'));const search=field(library,'search','Search projects'),filter=field(library,'filter','Lifecycle','ACTIVE',{options:['ACTIVE','ARCHIVED','ALL']}),list=e('ul');library.append(list);
  function drawList(){list.replaceChildren();const found=projects.filter(p=>(filter.value==='ALL'||p.lifecycle===filter.value)&&(p.title+' '+p.instrument.manufacturer+' '+p.instrument.model).toLowerCase().includes(search.value.toLowerCase()));for(const p of found){const li=e('li');li.append(e('strong',p.title),e('p',[p.instrument.manufacturer,p.instrument.model,p.instrument.year].filter(Boolean).join(' ')||'Instrument details can be added later'),e('small',p.lifecycle+' · Revision '+p.current_revision_id.slice(0,8)+' · Updated '+new Date(p.updated_at).toLocaleString()));button(li,'Open project',async()=>{await select(p.id);return 'Project workspace opened.';});list.append(li);}if(!found.length)list.append(e('li','No matching projects.'));}search.addEventListener('input',drawList);filter.addEventListener('change',drawList);drawList();root.append(library);
  let templateSection=null;const newSection=e('section'),newForm=e('form');newSection.append(e('h2','Start an instrument project'),e('p','Only a title is needed. Add instrument details as the work develops.'));field(newForm,'title','Project title','',{max:120,required:true});submit(newForm,'Create project',async f=>{const local={version:1,electronics:{version:1}},p=await repository.command('create',{snapshot:createSnapshot({title:value(f,'title')},local),name:'Initial design'});await refresh();await select(p.id);return 'Project created. Open its circuit to design in Forge.';});newSection.append(newForm);root.append(newSection);
  const localSection=e('details');localSection.append(e('summary','Import a local Free project'));const localEntries=store.list();localSection.append(e('p','Import is explicit. Browser originals are retained. Repeating an import opens the same cloud project.'));for(const row of localEntries.entries)button(localSection,'Import '+(row.project.name||'Untitled circuit'),async()=>{const p=await repository.command('create',{snapshot:createSnapshot({title:row.project.name},row.project),name:'Imported Free design',source_kind:'LOCAL_IMPORT',source_id:row.id});await refresh();await select(p.id);return 'Imported successfully. Your local original is unchanged.';});if(localEntries.notice)localSection.append(e('p',localEntries.notice));
  try{const incoming=JSON.parse(session.getItem('apparition.forge-pro.import')||'null');if(incoming?.local)button(localSection,'Import the design sent from Forge',async()=>{const p=await repository.command('create',{snapshot:createSnapshot({title:incoming.local.name||'Forge design'},incoming.local),name:'Imported editor design',source_kind:'LOCAL_IMPORT',source_id:incoming.id});session.removeItem('apparition.forge-pro.import');await refresh();await select(p.id);return 'Design saved to cloud. Existing local saves are unchanged.';});}catch{localSection.append(e('p','The pending design could not be read; the source was retained.'));}root.append(localSection);
  if(can('templates')){const section=e('section');templateSection=section;section.append(e('h2','Personal templates'));if(!templates.length)section.append(e('p','Save a project revision as a template to repeat useful work.'));for(const t of templates){const item=e('div');item.append(e('strong',t.name),e('p',t.description));button(item,'Start project from template',async()=>{validateSnapshot(t.snapshot);const p=await repository.command('instantiate',{template_id:t.id,name:'From '+t.name});await refresh();await select(p.id);return 'Independent project created with template provenance.';});section.append(item);}root.append(section);}
  const backToLibrary=()=>{rememberDraft();project=null;revisions=[];measurements=[];documents=[];comparisonResult=null;activeView='library';const url=new URL(location.href);url.searchParams.delete('project');doc.defaultView.history.replaceState(null,'',url.pathname+url.search);render();shellInstance?.focusWorkspace();};
  if(!project){shellInstance=mountProjectShell({root,status,library,creation:newSection,imports:localSection,templates:templateSection,onLibrary:backToLibrary,activeView,onView:v=>{activeView=v;}});return;}
  const detail=e('section');detail.className='forge-pro-detail';detail.tabIndex=-1;root.setAttribute('data-project-id',project.id);button(detail,'Back to Projects',()=>{backToLibrary();return 'Your project library.';});detail.setAttribute('aria-label','Current instrument project');detail.append(e('h2',project.title),e('p','Cloud project · '+project.lifecycle+' · Revision '+current().sequence+' · '+project.id));
  const saved=current().snapshot,unsaved=pending(),pendingState=JSON.parse(session.getItem('apparition.forge-pro.pending')||'null'),stalePending=!!unsaved&&pendingState.version!==project.version;if(unsaved)detail.append(e('p','Unsaved editor design is ready below. Save a revision to commit it; the cloud original remains unchanged.'));
  if(unsaved)button(detail,'Fork pending design into a separate project',async()=>{const info=JSON.parse(session.getItem('apparition.forge-pro.pending'));if(!info.fork_id){info.fork_id=globalThis.crypto.randomUUID();session.setItem('apparition.forge-pro.pending',JSON.stringify(info));}const p=await repository.command('create',{snapshot:createSnapshot({title:(project.title+' fork').slice(0,120)},unsaved),name:'Forked editor design',source_kind:'LOCAL_IMPORT',source_id:info.fork_id});session.removeItem('apparition.forge-pro.pending');await refresh();await select(p.id);return 'Pending design preserved in an independent project.';});const form=e('form');form.dataset.projectMetadata=project.id;form.addEventListener('input',()=>{form.dataset.dirty='true';});form.addEventListener('change',()=>{form.dataset.dirty='true';});field(form,'title','Project title',project.title,{max:120,required:true});field(form,'notes','Project notes',project.notes,{max:8000});const more=e('details');more.append(e('summary','Instrument record (optional)'));for(const key of instrumentFields)field(more,'instrument_'+key,key[0].toUpperCase()+key.slice(1),project.instrument[key],{max:key==='notes'?4000:200});form.append(more);field(form,'revision_name','Revision name','Design update',{max:120,required:true});field(form,'revision_note','Revision note','',{max:4000});
  submit(form,'Save new revision',async f=>{const pendingState=JSON.parse(session.getItem('apparition.forge-pro.pending')||'null');if(unsaved&&pendingState.version!==project.version)throw Error('The cloud project changed while this design was being edited. Your pending design is retained; import it into a separate project or review the new revision before saving.');const local=unsaved||localFromSnapshot(saved),p=await repository.command('save',{project_id:project.id,expected_version:project.version,snapshot:createSnapshot(metadata(f),local),name:value(f,'revision_name'),note:value(f,'revision_note')});session.removeItem('apparition.forge-pro.pending');await refresh();await select(p.id);return 'New immutable revision saved.';});for(const input of form.querySelectorAll('input,textarea,button'))input.disabled=project.lifecycle==='ARCHIVED';detail.append(form);if(metadataDraft?.project_id===project.id&&metadataDraft.version===project.version){form.dataset.dirty=String(metadataDraft.dirty);}if(metadataDraft?.project_id===project.id&&metadataDraft.version===project.version)for(const [name,val] of Object.entries(metadataDraft.values)){const n=form.elements.namedItem(name);if(n)n.value=val;}
  const electronics=e('section');electronics.append(e('h3','Design / Circuit'),e('p','Open the saved circuit in the same Forge application. Return the editor design for an explicit cloud revision. Existing browser saves remain intact.'));
  button(electronics,'Open circuit in Forge',()=>{const local=unsaved||localFromSnapshot(saved);session.setItem('apparition.forge-pro.editor',JSON.stringify({project_id:project.id,owner_id:identity.id,version:project.version,title:project.title,revision:'V'+current().sequence+' · '+current().name,local}));navigate(deploymentPath(projectURL('/circuit-forge/',local)));return 'Opening circuit editor…';},{disabled:project.lifecycle==='ARCHIVED'||stalePending});
  button(detail,'Duplicate project',async()=>{validateSnapshot(saved);const p=await repository.command('duplicate',{project_id:project.id});await refresh();await select(p.id);return 'Independent duplicate created.';});button(detail,'Archive project',async()=>{if(!globalThis.confirm('Archive this instrument project? Its revisions remain available.'))return 'Archive cancelled. No changes saved.';await repository.command('archive',{project_id:project.id,expected_version:project.version});await refresh();await select(project.id);return 'Project archived.';},{disabled:project.lifecycle==='ARCHIVED'});
  let historySection=null,comparisonSection=null,measurementSection=null,documentSection=null;
  for(const c of saved.technical.components){const b=e('button',c.label||c.id);b.type='button';b.dataset.inspectComponent=JSON.stringify(c);electronics.append(b);}
  if(can('history')){const history=e('section');historySection=history;history.append(e('h3','Durable revisions'));for(const r of revisions){const row=e('div');row.append(e('strong','V'+r.sequence+' · '+r.name),e('p',r.note),e('small',r.created_at));const inspect=e('button','Inspect V'+r.sequence);inspect.type='button';inspect.dataset.inspectRevision=JSON.stringify({id:r.id,sequence:r.sequence,name:r.name,note:r.note,created_at:r.created_at});row.append(inspect);button(row,'Restore as new revision',async()=>{validateSnapshot(r.snapshot);if(!globalThis.confirm('Create a new revision from V'+r.sequence+'? Historical revisions will not change.'))return 'Restore cancelled.';const p=await repository.command('restore',{project_id:project.id,expected_version:project.version,revision_id:r.id,name:'Restored V'+r.sequence});await select(p.id);await refresh();return 'Restored into a new revision.';},{disabled:project.lifecycle==='ARCHIVED'});history.append(row);}detail.append(history);}
  if(can('compare')&&can('history')){const comparison=e('section');comparisonSection=comparison;comparison.dataset.comparable=String(revisions.length>=2);comparison.append(e('h3','Compare revisions'));const la=e('label','Before'),lb=e('label','After'),sa=e('select'),sb=e('select');sa.setAttribute('aria-label','Before revision');sb.setAttribute('aria-label','After revision');for(const r of revisions)for(const n of [sa,sb]){const o=e('option','V'+r.sequence+' '+r.name);o.value=r.id;n.append(o);}if(revisions.length>1)sa.value=revisions[1].id;la.append(sa);lb.append(sb);comparison.append(la,lb);const output=e('div');button(comparison,'Compare structured changes',()=>{requireCapability(grants,capabilities.compare);const report=compareRevisions(revisions.find(r=>r.id===sa.value).snapshot,revisions.find(r=>r.id===sb.value).snapshot);comparisonResult=report;return 'Comparison complete.';});if(comparisonResult){output.append(e('p',comparisonResult.reason));for(const change of comparisonResult.changes)output.append(e('p',change.path+': '+JSON.stringify(change.before)+' → '+JSON.stringify(change.after)));if(comparisonResult.supported&&!comparisonResult.changes.length)output.append(e('p','No structured settings or metadata differences.'));}comparison.append(output);detail.append(comparison);}
  if(can('templates')){const f=e('form');f.append(e('h3','Reuse this revision'));field(f,'template_name','Template name',project.title,{required:true,max:120});field(f,'description','Template description','',{max:4000});submit(f,'Save as personal template',async()=>{await repository.command('template',{project_id:project.id,name:value(f,'template_name'),description:value(f,'description')});await refresh();return 'Immutable template saved.';});if(templateSection)templateSection.append(f);else detail.append(f);}
  if(can('measurements')){const section=e('section'),f=e('form');measurementSection=section;section.append(e('h3','Bench measurements'),e('p','Manual observations remain distinct from specified values. DCR is not an output or tone rating.'));const type=field(f,'type','Measurement type','resistance',{options:Object.keys(measurementTypes)}),unit=field(f,'unit','Unit','ohm',{options:measurementTypes.resistance});type.addEventListener('change',()=>{unit.replaceChildren();for(const v of measurementTypes[type.value]){const o=e('option',v);o.value=v;unit.append(o);}});field(f,'value','Measured value','',{type:'number',required:true});field(f,'nominal','Nominal value (same unit, optional)','',{type:'number'});field(f,'component_id','Component instance (optional)','',{options:['',...saved.technical.components.map(c=>c.id)]});field(f,'observed_at','Observed at (local time)',new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16),{type:'datetime-local',required:true});field(f,'notes','Measurement notes','',{max:2000});submit(f,'Record measurement',async()=>{const m=normaliseMeasurement(Object.fromEntries(['type','unit','value','nominal','component_id','observed_at','notes'].map(k=>[k,value(f,k)])));await repository.command('measurement',{project_id:project.id,...m});measurements=await repository.measurements(project.id);return 'Manual measurement recorded.';});for(const n of f.querySelectorAll('input,select,textarea,button'))n.disabled=project.lifecycle==='ARCHIVED';section.append(f);for(const m of measurements){const inspect=e('button','Inspect measurement · '+m.type);inspect.type='button';inspect.dataset.inspectMeasurement=JSON.stringify(m);section.append(inspect);section.append(e('p',(m.component_id||'Instrument')+' · '+m.type+' · measured '+m.value+' '+m.unit+' · nominal '+(m.nominal??'not recorded')+' · observed in revision '+m.revision_id+' · '+m.observed_at));}detail.append(section);}
  if(can('documents')){const section=e('section');documentSection=section;section.append(e('h3','Technical Build Sheets'),e('p','Private revision-bound documents capture measurements associated with that revision at generation time. They are not public passports.'));button(section,'Generate current revision Build Sheet',async()=>{await repository.command('document',{project_id:project.id,revision_id:project.current_revision_id});documents=await repository.documents(project.id);return 'Immutable document record created.';});for(const d of documents)button(section,'Download / print Build Sheet · '+d.created_at,()=>{download(renderBuildSheet(buildSheetModel(d)),'forge-build-sheet-'+d.id+'.html');return 'Build Sheet downloaded. Open it locally and use Print / Save as PDF.';});detail.append(section);}root.append(detail);shellInstance=mountProjectShell({root,status,project,revision:current(),library,creation:newSection,imports:localSection,templates:templateSection,instrument:detail,electronics,history:historySection,comparison:comparisonSection,measurements:measurementSection,documents:documentSection,metadataForm:form,onLibrary:backToLibrary,activeView,onView:v=>{activeView=v;},pending:!!unsaved,dirty:!!metadataDraft?.dirty&&metadataDraft.project_id===project.id&&metadataDraft.version===project.version});shellInstance.focusWorkspace();
 }
 async function start(){const generation=++epoch;root.replaceChildren();say('Checking your private project access…');try{const {data,error}=await auth.getUser();if(generation!==epoch)return;if(error||!data?.user?.email_confirmed_at||data.user.is_anonymous){identity=null;grants=[];projects=[];templates=[];project=null;revisions=[];measurements=[];documents=[];metadataDraft=null;activeView='access';render();say('Sign in with a confirmed customer account.');return;}if(identity?.id!==data.user.id){metadataDraft=null;project=null;revisions=[];measurements=[];documents=[];activeView='library';}identity=data.user;grants=await repository.capabilities();if(generation!==epoch)return;if(can('cloud')){await refresh();const id=new URL(location.href).searchParams.get('project');if(id)await select(id);}if(generation===epoch){render();say(can('cloud')?'Your project library is ready.':'Free Forge remains available. Preview access is unavailable for this account.');}}catch(error){if(generation===epoch){root.replaceChildren();say(error.message);link(root,'Retry project access',location.pathname);link(root,'Continue in Free Forge','/circuit-forge/');}}}
 subscription=auth.onAuthStateChange?.(event=>{if(event==='SIGNED_OUT'){epoch++;metadataDraft=null;activeView='library';identity=null;grants=[];projects=[];templates=[];project=null;revisions=[];measurements=[];documents=[];session.removeItem('apparition.forge-pro.pending');session.removeItem('apparition.forge-pro.editor');render();say('Signed out. Private project data cleared from this view.');}});
 return {start,destroy(){epoch++;shellInstance?.destroy();subscription?.data?.subscription?.unsubscribe();root.replaceChildren();},state:()=>({project,projects,grants,identity,activeView})};
}
function defaultDownload(html,name){const url=URL.createObjectURL(new Blob([html],{type:'text/html'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
